// Level-up cards (original implementation), generated by the sim per player:
//   new        learn a move (only while there are free slots)
//   upgrade    level up a move you have
//   evolution  a max-level move whose required stat card you've taken (always offered when ready)
//   stat       a permanent stat card for the run, with a rolled rarity (rarity.ts); a card with a
//              ceiling (`cap`) isn't offered once it's reached
import { openChoice } from './choices.js';
import { presentPlayers, type Ctx } from './ctx.js';
import { addMove, canLevelUp, evolutionInfo, evolveMove, levelUpMove, moveById } from './moves.js';
import { addMaxHp, hasMove, healPlayer } from './players.js';
import { rarityTier, rollRarity, scaledCardEffect } from './rarity.js';
import type { CardOption, MoveState, PlayerState } from './state.js';

interface Candidate {
  w: number;
  card: CardOption;
}

/** Has this stat card reached its ceiling for the player (then it isn't offered)? */
export function atCeiling(ctx: Ctx, p: PlayerState, id: string): boolean {
  const e = ctx.d.statCard(id).effect;
  if (e.type === 'maxHp') return e.cap !== undefined && (p.cardAdd[id] ?? 0) >= e.cap;
  if (e.type !== 'stat' || e.cap === undefined) return false;
  if (e.op === 'add') return (e.capOf === 'cards' ? (p.cardAdd[id] ?? 0) : p[e.stat]) >= e.cap;
  const built = p.cardMul[id] ?? 1;
  // A multiplier below 1 (cooldown) has its ceiling below 1 too: a floor.
  return e.value < 1 ? built <= e.cap : built >= e.cap;
}

function candidates(ctx: Ctx, p: PlayerState): Candidate[] {
  const { d, rand } = ctx;
  const cfg = d.game.levelUp;
  const out: Candidate[] = [];

  // --- new moves ---
  if (p.slots.length < p.maxSlots) {
    // No more buffs past the cap: they deal no damage, and four of them leave a run stuck.
    const buffs = p.moves.filter((m) => m.kind === 'buff').length;
    const pool = d
      .movePool(p.types)
      .filter(
        (id) =>
          !hasMove(p, id) &&
          !p.banned.includes(id) &&
          !(buffs >= cfg.maxBuffMoves && d.move(id).kind === 'buff'),
      );
    for (const id of rand.pickN(pool, cfg.newMoveCandidates)) {
      out.push({ w: cfg.weights.newMove, card: { id: `new:${id}`, type: 'new', moveId: id } });
    }
  }

  // --- evolutions: max level + the required stat card taken ---
  const waiting = new Map<string, MoveState>(); // stat card → move waiting for it
  for (const m of p.moves) {
    const ev = evolutionInfo(ctx, p, m);
    if (!ev) continue;
    if (!ev.ready) {
      waiting.set(ev.needs, m);
      continue;
    }
    out.push({
      w: cfg.weights.evolution,
      card: { id: `evolution:${m.id}`, type: 'evolution', moveId: m.id },
    });
  }

  // --- upgrades of moves you have ---
  for (const m of p.moves) {
    if (!canLevelUp(ctx, m)) continue;
    out.push({
      w: cfg.weights.moveUpgrade,
      card: { id: `upgrade:${m.id}`, type: 'upgrade', moveId: m.id, toLevel: m.level + 1 },
    });
  }

  // --- stats: not at their ceiling; the ones that unlock an evolution are always in ---
  const stats = rand
    .pickN(
      cfg.statCards.filter((c) => !waiting.has(c.id) && !atCeiling(ctx, p, c.id)),
      cfg.statCandidates,
    )
    .concat(cfg.statCards.filter((c) => waiting.has(c.id)));
  for (const c of stats) {
    const evoFor = waiting.get(c.id);
    out.push({
      w: evoFor
        ? cfg.weights.statForEvolution
        : p.slots.length < p.maxSlots
          ? cfg.weights.statWithFreeSlots
          : cfg.weights.stat,
      card: {
        id: `stat:${c.id}`,
        type: 'stat',
        statId: c.id,
        ...(evoFor ? { unlocksEvolutionOf: evoFor.id } : {}),
      },
    });
  }
  return out;
}

/**
 * Up to `cardsOffered` distinct cards, picked by weight; a ready evolution is always one. From
 * `lateGrowth.offers.fromMinute`, the next slots go to offensive stat cards (Power / Reflexes)
 * not at a ceiling: one at random each, keeping a ready evolution's slot if configured. Then every
 * stat card that has rarities rolls one.
 */
export function offerCards(ctx: Ctx, p: PlayerState): CardOption[] {
  const n = ctx.d.game.levelUp.cardsOffered;
  const pool = candidates(ctx, p);
  const picked: CardOption[] = [];
  const used = new Set<string>();
  const take = (c: Candidate) => {
    used.add(c.card.id);
    picked.push(c.card);
  };
  const late = ctx.d.game.tuning.lateGrowth.offers;
  const guaranteed = ctx.s.time >= late.fromMinute * 60 ? late.guaranteedOffenseSlots : 0;
  const takeEvolution = () => {
    const evo = pool.findIndex((c) => c.card.type === 'evolution');
    const [c] = evo >= 0 ? pool.splice(evo, 1) : [];
    if (c && picked.length < n) take(c);
  };
  if (late.preserveReadyEvolution) takeEvolution();
  let offense = late.statIds.filter((id) => !atCeiling(ctx, p, id));
  const guaranteedIds: string[] = [];
  for (let i = 0; i < guaranteed && picked.length < n && offense.length; i++) {
    const id = ctx.rand.pick(offense);
    offense = offense.filter((o) => o !== id);
    // The candidate itself if it's in the pool (it may say which evolution it unlocks).
    const at = pool.findIndex((c) => c.card.id === `stat:${id}`);
    const [c] = at >= 0 ? pool.splice(at, 1) : [];
    take(c ?? { w: 0, card: { id: `stat:${id}`, type: 'stat', statId: id } });
    guaranteedIds.push(`stat:${id}`);
  }
  if (!late.preserveReadyEvolution) takeEvolution();
  while (picked.length < n && pool.length) {
    const total = pool.reduce((a, c) => a + c.w, 0);
    let r = ctx.rand() * total;
    let idx = 0;
    for (let i = 0; i < pool.length; i++) {
      r -= pool[i]?.w ?? 0;
      if (r <= 0) {
        idx = i;
        break;
      }
    }
    const [c] = pool.splice(idx, 1);
    if (!c || used.has(c.card.id)) continue;
    take(c);
  }
  // Not always in the same place: each guaranteed card moves to a random slot after the evolution.
  const first = picked[0]?.type === 'evolution' ? 1 : 0;
  for (const id of guaranteedIds) {
    const from = picked.findIndex((c) => c.id === id);
    const [card] = picked.splice(from, 1);
    if (card) picked.splice(first + Math.floor(ctx.rand() * (picked.length - first + 1)), 0, card);
  }
  const rarity = ctx.d.game.levelUp.rarity;
  return picked.map((c) =>
    c.type === 'stat' && c.statId && ctx.d.statCard(c.statId).rarity !== false
      ? { ...c, rarity: rollRarity(rarity, ctx.s.time / 60, ctx.rand) }
      : c,
  );
}

export function applyCard(ctx: Ctx, p: PlayerState, card: CardOption): void {
  const m = card.moveId ? moveById(p, card.moveId) : undefined;
  switch (card.type) {
    case 'new':
      if (card.moveId) addMove(ctx, p, card.moveId);
      return;
    case 'upgrade':
      if (m) levelUpMove(ctx, p, m);
      return;
    case 'evolution':
      if (m) evolveMove(ctx, p, m);
      return;
    case 'stat': {
      if (!card.statId) return;
      const c = ctx.d.statCard(card.statId);
      const tier = rarityTier(ctx.d.game.levelUp.rarity, card.rarity);
      const e = scaledCardEffect(c.effect, tier?.multiplier ?? 1);
      if (e.type === 'maxHp') {
        // Up to the ceiling on what this card's picks added; the heal is what was added.
        const had = p.cardAdd[c.id] ?? 0;
        const add = e.cap === undefined ? e.value : Math.max(0, Math.min(e.value, e.cap - had));
        p.cardAdd[c.id] = had + add;
        if (add > 0) addMaxHp(p, add);
      } else if (e.type === 'heal') healPlayer(ctx, p, p.maxHp * e.maxHpFraction);
      else if (e.op === 'add') {
        // The ceiling bounds the stat itself, or with `capOf: "cards"` what this card's picks added.
        const had = p.cardAdd[c.id] ?? 0;
        if (e.cap !== undefined && e.capOf === 'cards') {
          const built = Math.min(e.cap, had + e.value);
          p.cardAdd[c.id] = Math.max(had, built);
          p[e.stat] += Math.max(0, built - had);
        } else {
          const v = p[e.stat] + e.value;
          const next = e.cap === undefined ? v : Math.max(p[e.stat], Math.min(e.cap, v));
          p.cardAdd[c.id] = had + (next - p[e.stat]);
          p[e.stat] = next;
        }
      } else {
        // The ceiling bounds what this card's picks have built up; the stat moves by the same step.
        const had = p.cardMul[c.id] ?? 1;
        let built = had * e.value;
        if (e.cap !== undefined)
          built = e.value < 1 ? Math.max(e.cap, built) : Math.min(e.cap, built);
        p.cardMul[c.id] = built;
        p[e.stat] *= built / had;
      }
      // Once per pick whatever the rarity: evolutions only need the card taken.
      p.statsTaken[c.id] = (p.statsTaken[c.id] ?? 0) + 1;
    }
  }
}

/** Hands out the next round of level-up cards, one choice per player, when nothing is pending. */
export function maybeLevelUp(ctx: Ctx): void {
  const { s } = ctx;
  if (s.pendingLevels <= 0 || s.pendingChoices.length) return;
  const players = presentPlayers(s);
  // Never open cards with everyone down (dying and picking up XP on the same tick).
  if (!players.length || players.every((p) => p.dead)) return;
  s.pendingLevels--;
  for (const p of players) {
    openChoice(ctx, {
      kind: 'level-up',
      playerId: p.id,
      level: s.team.level - s.pendingLevels,
      options: offerCards(ctx, p),
    });
  }
}
